/**
 * Golden-fixture parity test — the TS evaluator must agree with the backend evaluator
 * on every case the backend computed.
 *
 * The fixture is generated by `poetry run python manage.py export_osp_module_fixture`,
 * which serializes the registry AND runs each answer battery through the PYTHON
 * evaluator. This test replays the same batteries through conditionEval.ts. A failure
 * here means the two evaluators diverged — fix the semantics, then regenerate.
 */

import { describe, expect, it } from 'vitest';

import { missingRequired, visibleQuestions } from '../conditionEval';
import type { ModuleDefinition, ModuleRegistryResponse } from '../types';
import fixture from './fixtures/module-definitions.json';

interface GoldenCase {
  module: string;
  label: string;
  answers: Record<string, unknown>;
  visible_questions: string[];
  missing_required: string[];
  missing_required_na: string[];
}

const registry = fixture.registry as ModuleRegistryResponse;
const goldenCases = fixture.golden_cases as GoldenCase[];
const modulesByKey = new Map(registry.modules.map((m) => [m.key, m]));

describe('conditionEval parity with the backend evaluator', () => {
  it('fixture is present and non-trivial', () => {
    expect(registry.modules.length).toBeGreaterThanOrEqual(3);
    expect(goldenCases.length).toBeGreaterThanOrEqual(10);
  });

  for (const goldenCase of goldenCases) {
    const name = `${goldenCase.module} · ${goldenCase.label}`;
    it(`${name}: visible questions match`, () => {
      const module = modulesByKey.get(goldenCase.module) as ModuleDefinition;
      expect(module).toBeDefined();
      const visible = visibleQuestions(module, goldenCase.answers as never).map(
        ({ question }) => question.key
      );
      expect(visible).toEqual(goldenCase.visible_questions);
    });

    it(`${name}: missing-required matches`, () => {
      const module = modulesByKey.get(goldenCase.module) as ModuleDefinition;
      expect(missingRequired(module, goldenCase.answers as never)).toEqual(
        goldenCase.missing_required
      );
      expect(missingRequired(module, goldenCase.answers as never, true)).toEqual(
        goldenCase.missing_required_na
      );
    });
  }
});
